import { test, expect } from '@playwright/test';

test('floor calibration drawing, errors, save and reload', async ({ page }) => {
  test.setTimeout(90000);
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.addInitScript(() => localStorage.setItem('cctv-language', 'id'));
  await page.goto('/#/live');
  if (await page.locator('.camera-session-controls').evaluate(element => !element.open)) await page.locator('.camera-session-controls > summary').click();
  await page.getByRole('button', { name: 'Lanjut ke cek koneksi', exact: true }).click();
  await page.getByRole('button', { name: 'Hubungkan webcam', exact: true }).click();
  await expect(page.getByTestId('webcam-status')).toContainText('Live');
  await page.locator('.setup-progress button').nth(2).click();
  await page.getByRole('button', { name: 'Atur zona', exact: true }).click();
  const modal = page.getByRole('dialog');
  const addPoint = async (x, y) => {
    await modal.getByLabel('Koordinat X (0 sampai 1)').fill(String(x));
    await modal.getByLabel('Koordinat Y (0 sampai 1)').fill(String(y));
    await modal.getByRole('button', { name: 'Tambah titik koordinat', exact: true }).click();
  };
  for (const row of await modal.locator('.calibration-zone-row').all()) await row.getByRole('button', { name: 'Hapus zona' }).click();
  await modal.getByLabel('Metode penentuan zona').selectOption('footpoint');
  await modal.getByLabel('Toleransi batas (fraksi gambar)').fill('0.02');
  await modal.getByLabel('Metode penentuan zona').selectOption('homography');
  await modal.getByLabel('Nama zona live', { exact: true }).fill('Zona lantai uji');
  await addPoint(0.2, 0.2);
  await modal.getByRole('button', { name: 'Batalkan zona', exact: true }).click();
  await modal.getByLabel('Nama zona live', { exact: true }).fill('Zona lantai uji');
  for (const point of [[0.1, 0.1], [0.9, 0.1], [0.9, 0.9], [0.1, 0.9]]) await addPoint(...point);
  await modal.getByRole('button', { name: 'Simpan zona', exact: true }).click();
  await modal.getByRole('button', { name: 'Simpan kalibrasi live', exact: true }).click();
  await expect(modal.getByRole('alert')).toContainText('empat sudut');
  await modal.getByLabel('Gambar pada frame').selectOption('floor');
  for (const point of [[0, 0], [1, 0], [1, 1], [0, 1]]) await addPoint(...point);
  await addPoint(0.5, 0.5);
  await expect(modal.getByRole('alert')).toContainText('sudah lengkap');
  await modal.getByRole('button', { name: 'Urungkan titik', exact: true }).click();
  // Exercise pointer mapping as well as the keyboard coordinate inputs.
  const frame = modal.locator('.calibration-frame');
  const bounds = await frame.boundingBox();
  await frame.click({ position: { x: 1, y: bounds.height - 1 } });
  await modal.getByRole('button', { name: 'Urungkan titik', exact: true }).click();
  await addPoint(0, 1);
  await modal.getByLabel('Lebar lantai nyata (meter)').fill('6');
  await modal.getByLabel('Kedalaman lantai nyata (meter)').fill('8');
  await modal.getByLabel('Toleransi batas (meter)').fill('0.1');
  await modal.getByRole('button', { name: 'Edit zona', exact: true }).click();
  await modal.getByRole('button', { name: 'Simpan zona', exact: true }).click();
  await modal.getByLabel('Metode penentuan zona').scrollIntoViewIfNeeded();
  await page.screenshot({ path: '../runtime/calibration-browser-desktop.png', fullPage: true });
  await page.setViewportSize({ width: 390, height: 844 });
  expect(await modal.evaluate(element => element.scrollWidth <= element.clientWidth + 1)).toBe(true);
  await modal.getByLabel('Metode penentuan zona').scrollIntoViewIfNeeded();
  await page.screenshot({ path: '../runtime/calibration-browser-mobile.png', fullPage: true });
  await page.setViewportSize({ width: 1440, height: 1000 });
  await modal.getByLabel('Toleransi batas (meter)').fill('5');
  await modal.getByRole('button', { name: 'Simpan kalibrasi live', exact: true }).click();
  await expect(modal.getByRole('alert')).toContainText('terlalu besar');
  await modal.getByLabel('Toleransi batas (meter)').fill('0.1');
  await modal.getByRole('button', { name: 'Simpan kalibrasi live', exact: true }).click();
  await expect(modal).not.toBeVisible();
  const profile = (await (await page.request.get('/pilot/v1/live')).json()).calibrations.WEBCAM_LIVE;
  expect(profile.position.mode).toBe('homography');
  expect(profile.position.image_points).toEqual([[0, 0], [1, 0], [1, 1], [0, 1]]);
  expect(profile.position.floor_width_m).toBe(6);
  await page.locator('.setup-progress button').nth(2).click();
  await page.getByRole('button', { name: 'Atur zona', exact: true }).click();
  await expect(modal.getByLabel('Metode penentuan zona')).toHaveValue('homography');
  await expect(modal.getByLabel('Lebar lantai nyata (meter)')).toHaveValue('6');
  await modal.getByRole('button', { name: 'Batal', exact: true }).click();
  await page.getByRole('button', { name: 'Atur zona', exact: true }).click();
  await page.keyboard.press('Tab');
  expect(await modal.evaluate(element => element.contains(document.activeElement))).toBe(true);
  await page.keyboard.press('Escape');
  await expect(modal).not.toBeVisible();
  await page.getByRole('button', { name: 'Atur zona', exact: true }).click();
  await modal.getByRole('button', { name: 'Tutup dialog', exact: true }).click();
  expect(errors).toEqual([]);
});
